%=============================================================================
%
% FORMAT 
%	 e = fom_seaice_emis_surfem(freq, eia, lat, lon, dircli, mm, dd, sit, snt, sia, sir, skt, tcwv )
%
% DESCRIPTION
%
%	SURface Fast Emissivity Model for Sea Ice (SURFEM-SeaIce) developed
%	by Catherine Prigent, Iris de Gelis, Lise Kilic and Carlos Jimenez
%	as part of the ESA CIMR SCEPS project.
%
%	It provides the V-pol and H-pol emissivity (emis) for a given lat-lon location
%       and a number of frequencies and Earth incidence angles. There is no frequency
%	interpolation and the emis corresponds to the microwave imager channels 
%	1.41 6.925 10.65 18.7 or 36.5 GHz. There is an interpolation in frequency
%       and, althoug the emis parameterization is derived mainly using observations
%       at the SMAP (40deg) and AMSR2 (55deg) incidence angles, any angle between
%	0 and 90 can be given.
%
%  It  works in two modes: 
%
%	    (1) to output a "climatological" emis value from a file. This mode 
%	    is activated if no geo-physical inputs are given. To be run as:
%
%	       e = fom_seaice_emis_surfem(freq, eia, lat, lon, dircli, mm, dd)
%	
%	    (2) to output a "dynamical" emis value from a parameterizations driven 
%	    by the geo-physical inputs. This mode can only be used for the winter
%	    months of November to May, with likely larger emissivity uncertainty
%	    for November and May, compared with the other winter months. To be 
%	    run as:
%
%	       e = fom_seaice_emis_surfem(freq, eia, [], [], [], mm, dd, sit, snt, sia, sir, skt, tcwv )
%
%	     	
%	
% OUT  
%	e                 emissivty values as a matrix of dimensions 
%			  2 (v-pol and h-pol) x number of freq x number of eia
%
% IN    
%	freq	[GHz]     Frequency, it should be one of the CIMR frequencies: 1.41 6.925 10.65 18.7 or 36.5
%	eia	[deg]     Earth incidence angle between 0 and 90
%	lat     [deg]	  Latitude 
%	lon     [deg]	  Longitude between -180 and +180
%	dircli		  Folder where the ancillary files where the climaological
%			  emis are found. 
%	mm                Numeric month of the year
%	dd                Numeric day of the month
%	sit	[m]	  Sea Ice Thickness
%			      (nextSIM "sithick"  used in paremeterization derivation)
%	snt	[m]       Surface Snow Thickness (neXtSIM)
%			      (nextSIM "sisnthick"  used in paremeterization derivation)
%	sia	[years]   Sea Ice Age, siage
%			      (nextSIM "siage"  used in paremeterization derivation)
%	sir	[-]       Sea Ice Roughness
%			      (nextSIM product of "si_ridge_ratio" and "sithick", 
%			       used in paremeterization derivation)
%	skt	[K]       Skin Temperature
%			      (ERA5 "skt"  used in paremeterization derivation)
%	tcwv	[kg/m2]	  Total Column Water Vapor
%			      (ERA5 "tcwv"  used in paremeterization derivation)
%
% REFERENCES
%
%        Kilic, L., Jimenez, C., Prigent, C., Korosov, A., Rampal, P., de Gelis, I., and Garric, G., 
%	 Parameterization of the winter Arctic sea ice microwave emissivity between 1.4 and 36~GHz, 
%        for large scale applications, DOI: 10.1029/2025EA004259.
%
%	 Funded by ESA contract 4000138129/22/NLIA. 
% 
% HISTORY
%
%	2024-12-15	iris.degelis(at)estellus.fr: created as part of the ESA CIMR SCEPS project
%
%	2025-06-15	carlos.jimenez(at)estellus.fr: adapted to produce multi-angle-frequency emis
%
%	2025-08-06	carlos.jimenez(at)estellus.fr: adding some code documentation
%
%============================================================================================


function e = fom_seaice_emis_surfem(freq, eia, lat, lon, dircli, mm, dd, sit, snt, sia, sir, skt, tcwv )


nin = length(eia);
len = length(freq);


%=== checking inputs for working modes

if nargin > 7

  %= dynamical emissivity driven by geo-inputs
  %  fast, it is coded using NNs

  %= checking months

  if mm > 5 & mm < 11

    disp( 'Dynamical emissivity is only allowed for winter months, from November to May, revert to a climatological calculation for this month' ) 
    e  = []; 
    return

  end


  %= winterday since 01/10
  winterday = get_winterday(dd, mm);

  %= nn inputs

  inputs = [sit; snt; sia; sir; skt; tcwv; winterday];

  %= emis per frequency and angle

  e_v = nan( nin,len);
  e_h = nan( nin,len);

  for k = 1:len
    [e_v(:,k),e_h(:,k)] = get_emis_freq_incident_angle(inputs, freq(k), eia); 
  end


else

  %= climatological emis if no geo-inputs
  %  slower processing due to need to load
  %  the emis files and non-optimized codes
  %  for the moment

  e_v = nan( nin,len);
  e_h = nan( nin,len);

  for k = 1:len

    %=== identifying climatological emis to load

   [doy_clim, grid, sat, group, idx_col, idx_row, idx_v, idx_h] = which_climato(mm, dd, lat, lon, freq(k));
 
    %=== emis file

    path_clim_file = fullfile( dircli, 'Climatologies', grid, sat, sprintf("Emissivity_for_%s_%s_%s_%03d.mat", sat, group, grid, doy_clim));
    
    %=== loading emis from file

    clim = load(path_clim_file).data;
    clim_v = clim(1, idx_row,idx_col, idx_v);
    clim_h = clim(1, idx_row,idx_col, idx_h);

    %= adding angular dependence 

    [e_v(:,k),e_h(:,k)] = get_emis_freq_incident_angle([], freq(k), eia, [clim_v;clim_h]); 

  end

end

%= emis returned as v-h x n freqs x n ang

e = nan( 2, len, nin );
e(1,:,:) = e_v';
e(2,:,:) = e_h';

return

%------------------------------------------------------------
% Winterday since 01/10

function winterday = get_winterday(dd, mm )


% days in month

days = [31 28 31 30 31 30 31 31 30 31 30 31];

winterday = 0;
months    = [10:12 1:6];
ended     = false;

m = 1;
while m<numel(months) & ~ended
    mo = months(m);
    if mm==mo
        winterday = winterday + dd;
        ended = true;
    else
        winterday = winterday + days(m);
    end
    m = m+1;
end

return



%------------------------------------------------------------------------
% core function deriving the emis values for frequency and angle

function [e_v,e_h] = get_emis_freq_incident_angle(inputs, freq, theta, emis)

%= emis computation at 55deg for frequency from 6.9 to 36.5 GHz, and 40deg for 1.4 GHz 

if ~isempty( inputs )

  [ W1, b1, W2, b2, ti, to ] = get_nn_weight(freq);
  [emis] = apply_nn(inputs, W1, b1, W2, b2, ti, to);

end


if freq==1.41

%=  INTERNAL NOTES: 
%   - at 1.4 GHz, polynom (degree 2) derived from SMOS angular dependence and fitted
%   to SMAP. 
%    - adjustements on the value at nadir (pv(3)=ph(3)=e0) and then adjustements on pv(2) and ph(2).
%   pv(1) and ph(1) not changed (the curvature).

    [pv_ori, ph_ori] = polynomial_1ghz;
    pv(3,:)=emis(1,:)-pv_ori(2)*40-pv_ori(1)*40^2;
    ph(3,:)=emis(2,:)-ph_ori(2)*40-ph_ori(1)*40^2;
    pv(3,:)=(pv(3,:)+ph(3,:))/2.; % V+H/2 --> on suppose qu'à 40° on est à la moitié
    ph(3,:)=pv(3,:);
    pv(2,:)=(emis(1,:)-pv(3,:)-pv_ori(1)*40^2)/40;
    ph(2,:)=(emis(2,:)-ph(3,:)-ph_ori(1)*40^2)/40;
    pv(1,:)=pv_ori(1);
    ph(1,:)=ph_ori(1);
    for i=1:size(emis,2)
        e_v(:,i)=polyval(pv(:,i),theta);
        e_h(:,i)=polyval(ph(:,i),theta);
    end


elseif freq>1 & freq<18

%=   INTERNAL NOTES:
%    - at 6 and 10 GHz, the angular dependence is derived from the 1.4 GHz dependence (above) 
%    and from TELSEM2 at 18 GHz. 
%    - for TELSEM2, class8 is selected after some tests: limited differences between class 7 
%    to 9 and the intermediate one is selected.
%    - e0 is a (frequency proportional) mix between the value calculated from the 1.4GHz angular 
%    dependence  (corresponding at the 55°) and e0 directly calculated from TELSEM
%    - curvature (theta*theta) is from 1.4 GHz derived from SMOS  (all SIT averaged). 
%    - the other coeff (theta) to fit the estimated values at 55°

    [pv_ori, ph_ori] = polynomial_1ghz;
    [a0_k0, a0_k1, a0_k2, a0_eveh, a1_eveh, a2_eveh, a3_eveh, b0_eveh, b1_eveh, b2_eveh, b3_eveh] = telsem2_coef;
    theta55 = 55;
    e0_1v=emis(1,:)-pv_ori(2)*theta55-pv_ori(1)*theta55*theta55;
    e0_1h=emis(2,:)-ph_ori(2)*theta55-ph_ori(1)*theta55*theta55;
    e0_1=(e0_1v+e0_1h)/2.;
    e0_18 = a0_k0(1,8)+a0_k1(1,8)*emis(1,:)+a0_k2(1,8)*emis(2,:);
    pv(3,:)=(freq-1.4)*(e0_18-e0_1)/(18-1.4)+e0_1;
    ph(3,:)=pv(3,:);
    % Coef (in theta) to fit the value at emis value at 55°.
    pv(2,:)=(emis(1,:)-pv(3,:)-pv_ori(1)*theta55*theta55)/theta55;
    ph(2,:)=(emis(2,:)-ph(3,:)-ph_ori(1)*theta55*theta55)/theta55;
    % Curvature (theta*theta) is from 1.4 GHz derived from SMOS.
    pv(1,:)=pv_ori(1);
    ph(1,:)=ph_ori(1);
    for i=1:size(emis,2)
        e_v(:,i)=polyval(pv(:,i),theta);
        e_h(:,i)=polyval(ph(:,i),theta);
    end

else

%=   INTERNAL NOTES: 
%    - at 18 and 36 GHz, TELSEM2 for class1=8 is used to provide 
%    the angulardependence.

    [a0_k0, a0_k1, a0_k2, a0_eveh, a1_eveh, a2_eveh, a3_eveh, b0_eveh, b1_eveh, b2_eveh, b3_eveh] = telsem2_coef;
    class1=8;  % class1=8 from TELSEM2
    telsem_idx = dictionary([18.7, 36.5, 89],[1,2,3]);
    j=telsem_idx(freq); % 18 GHz is the first channel in TELSEM2
    e0 = a0_k0(j,class1)+a0_k1(j,class1)*emis(1,:)+a0_k2(j,class1)*emis(2,:);
    a0 = a0_eveh(j,class1);
    a1 = a1_eveh(j,class1);
    a2 = a2_eveh(j,class1);
    a3 = a3_eveh(j,class1);
    b0 = b0_eveh(j,class1);
    b1 = b1_eveh(j,class1);
    b2 = b2_eveh(j,class1);
    b3 = b3_eveh(j,class1);
    theta0 = 0.;
    theta55 = 55.; % coefficient calculated for inputs at 53° in TELSEM2, but little difference expected with 55° (given the error bar).
    %%% Vertical polarization
    S1_v = ((theta-theta55)/(theta0-theta55)) * ((e0-a0)/a0);
    em55_v = a3*(theta55^3) + a2*(theta55^2) + a1*theta55 + a0;
    S2_v =((theta-theta0)/(theta55-theta0))*((emis(1,:)-em55_v)/em55_v);
    S_v = 1 + S1_v + S2_v;
    emtheta_v = a3*(theta.^3) + a2*(theta.^2) + a1*theta + a0;
    e_v = S_v .* emtheta_v;
    %%% Horizontal polarization
    S1_h = ((theta-theta55)./(theta0-theta55)) * ((e0-b0)/b0);
    em55_h = b3*(theta55.^3) + b2*(theta55.^2) + b1*theta55 + b0;
    S2_h =((theta-theta0)./(theta55-theta0)).*((emis(2,:)-em55_h)./em55_h);
    S_h = 1 + S1_h + S2_h;
    emtheta_h = b3*(theta.^3) + b2*(theta.^2) + b1*theta + b0;
    e_h = S_h .* emtheta_h;

end

return



%------------------------------------------------------------------------
%
% NAME:    [ Y ] = apply_nn( X, W1, b1, W2, b2, ti, to)
%
%          Calculates the output of a NN net. The net has to be a MLP 
%          with mapminmax applied to input and
%	   outputs, a first (hidden) layer with tansig activation functions
%	   and a second (output) layer with purelin functions. See the code
%	   below to see how the NN, mapminmax, and J, are implemented as
%	   matrix multiplications.
%
% OUT:	Y	net output for X, matrix [no * ns]
%
% IN:	X   net input, matrix [ni * ns]
%	W1	weight matrix of first layer, matrix [nh * ni]
%	b1	bias vector of first layer, vector [nh * 1]
%	W2	weight matrix of second layer, matrix [no * nh]
%	b2	bias vector of first layer, vector [no * 1]
%   ti	structure having the settings of the input
%		mapminmax transformation
%   to	structure having the settings of the output
%		mapminmax transformation
%
%------------------------------------------------------------------------

function [Y] = apply_nn( X, W1, b1, W2, b2, ti, to )


%=== NN output with matrices

% number of samples
nx = size( X, 2 );
% number of inputs nodes
ni = size( W1, 2 );
% number of outputs nodes
no = size( W2, 1 );
% number of nodes in hidden layer
nh = size( W1, 1);


%= input transformed with mapminmax
%      y = (ymax-ymin)*(x-xmin)/(xmax-xmin) + ymin;
%  but coded with a ymin, offset and gain as
%      y = iymi + (x - offset).* gain;

igai = ti.gain;
igai = repmat( igai, 1, nx);
ioff = ti.xoffset;
ioff = repmat( ioff, 1, nx);
iymi = ti.ymin;
iymi = repmat( iymi, 1, nx);

aux = iymi + (X - ioff).* igai;

%= propagation through first with layer W1 b1 and tansig

x1  = W1 * aux + b1;
aux = 2 ./ (1+exp(-2 * x1 ) ) -1;


%= propagation through output layer with W2 and b2 and purelin

aux = W2 * aux + b2;

%= output transformed back with mapminmax

ogai = to.gain;
ogai = repmat( ogai, 1, nx);

ooff = to.xoffset;
ooff = repmat( ooff, 1, nx);

oymi = to.ymin;
oymi = repmat( oymi, 1, nx);

Y = ((aux - oymi ) ./ ogai ) + ooff;

return

%------------------------------------------------------------------------
% Selecting NN weights as function of frequency

function [ W1, b1, W2, b2, ti, to ] = get_nn_weight( freq )


if freq==1.41
    [ W1, b1, W2, b2, ti, to ] = nn_1GHz;
elseif freq==6.925
    [ W1, b1, W2, b2, ti, to ] = nn_6GHz;
elseif freq==10.65
    [ W1, b1, W2, b2, ti, to ] = nn_10GHz;
elseif freq==18.7
    [ W1, b1, W2, b2, ti, to ] = nn_18GHz;
elseif freq==36.5
    [ W1, b1, W2, b2, ti, to ] = nn_36GHz;
end

return

%------------------------------------------------------------------------
% hard Coding of NNs weights, one NN per frequency

