to.ymin  = -1.0000000e+00;


W1 = [0.498775095989736,-2.63711045553035,-0.374004813372179,0.777701411304376,0.00747668498674728,0.326927162500585,-0.207627250428288;-0.906949223974549,-0.207494543019609,0.532830978993566,-0.392228589552620,-0.378166265709420,-1.56988813965688,0.0309614268446436;1.28408814415663,0.218665411395094,-1.08284475173058,-0.720073117142231,-0.299295035374814,0.174027384038043,-1.02728681310191;1.55818206816440,2.01294797706587,0.814058681981599,-2.28892407582414,0.0895825420881583,-0.184992073643199,-0.687749945268486;-0.559535567712123,-0.943940870036392,0.0390227687442352,1.46951025640283,0.0434559768426006,-0.188858755816435,1.22276886439431;-1.20618998957992,0.411674273888748,-0.928831619168746,2.10532086732486,0.474559718278210,0.154677741223982,-0.0764174465129255;-0.978577345641482,0.196034174221673,-0.249101226386428,0.209136492651678,0.210771793964947,0.539018046437470,0.234306597380324;-0.462424528424626,-0.131742657212636,0.469571839822052,0.100019523026909,0.331422343605734,-0.846431650549728,-1.10171041821487;0.765169516279344,-0.383342646264927,-0.189212796106995,-0.230112841933315,-0.474317225665582,1.10929044272736,2.07073299426800;-1.13737566919627,0.140738255613993,0.525434776762006,-0.272724401372389,0.406192901492801,-1.22501774930153,0.0647046343390411;-2.75771957359893,-0.806453332384464,-0.526970009905532,2.46747873102462,0.406449826649856,-0.182762777546443,0.0887827499261852;-0.0280613131316532,0.536304537350355,-0.241456142635284,0.217701915261166,0.0291447655120726,-0.331492506947029,0.367210821655370;-0.194478892937272,-0.553668379512778,-0.992368025538528,0.515257628278930,1.01546577971821,0.324258899532661,-1.04087182158547;0.194657533211655,0.0239874029448011,-1.16230306947334,-0.186404197101100,0.194352121422360,-0.649979105416796,0.412226848132896;0.337851658287664,-0.687278785335467,-0.383433184709587,0.0936959554923397,0.580724253093337,-1.39107796904621,1.38368681443874;0.634665336610207,-0.459516924452474,0.624433201491001,0.8307986